    S_1 S_2 S_3 S_4 \le C_2 \sqrt{R_3 R_4} V(R) \label{eq:A}
\end{equation}
\begin{equation}
    S_1 S_2 S_3 S_4 \le C_2 \sqrt{R_2 R_3} V(R) \label{eq:B}
